window.docContents[119].resolve({"/rules/PL1004/#PL1004-limitations":{"contents":"The editor may defer authentication and report a pending result; the project command completes it.\n\nAn unauthenticated axiom that merely looks native is not compiler-trusting; it is rejected as an unknown axiom (PL1003) or project axiom (PL1001).\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL1004: Compiler-trusting proofs require separate classification","header":"Limitations and unsupported cases","id":"/rules/PL1004/#PL1004-limitations"},"/rules/PL2003/#PL2003-limitations":{"contents":"lake lint builds with linter.plumb weakly off, so Plumb's own local findings are not build warnings there and its policy stages report those rules; a source set_option linter.plumb true turns the local linter back on (issue #69). axiomGate and the build-lint policy target keep ordinary options, so in a module that imports Plumb.Linter a local Plumb finding is a build warning and makes the result INCOMPLETE under this rule.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL2003: Claimed source must elaborate warning-free","header":"Limitations and unsupported cases","id":"/rules/PL2003/#PL2003-limitations"},"/rules/PL3002/#PL3002-limitations":{"contents":"Proof search is deliberately incomplete: a candidate whose remaining premises cannot be instantiated supplies no evidence, and the boundary stays trusted.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL3002: Checked execution requires admitted correspondence","header":"Limitations and unsupported cases","id":"/rules/PL3002/#PL3002-limitations"},"/rules/PL4001/#PL4001-limitations":{"contents":"Only Markdown structure is checked here; elaboration results belong to PL4002–PL4004.\n\n","context":"Plumb for Lean rule reference\u0009Rule index\u0009PL4001: Documentation fences must have a valid classification","header":"Limitations and unsupported cases","id":"/rules/PL4001/#PL4001-limitations"}});